s."], ["Earnest money","Profession term \u2014 Earnest money: The buyer's good-faith deposit."], ["Contingency","Profession term \u2014 Contingency: Contract conditions like inspection or financing."], ["Appraisal","Profession term \u2014 Appraisal: Lender-required value opinion."], ["Inspection","Profession term \u2014 Inspection: Professional property examination."], ["Title search","Profession term \u2014 Title search: Verifying clean ownership history."], ["Closing","Profession term \u2014 Closing: The final signing and fund transfer."], ["Commission split","Profession term \u2014 Commission split: Agent/brokerage fee division."], ["Cap","Profession term \u2014 Cap: The annual fee limit before 100% commission."], ["FSBO","Profession term \u2014 FSBO: For Sale By Owner."], ["Days on market","Profession term \u2014 Days on market: Listing age metric."], ["Open house","Profession term \u2014 Open house: Public showing event."], ["Comparables","Profession term \u2014 Comparables: Recently sold similar homes."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
